create or replace function public.meu_acesso() returns jsonb language sql stable security definer set search_path=public,pg_temp as $$ select case when auth.uid() is null then jsonb_build_object('autenticado',false) else jsonb_build_object('autenticado',true,'perfil',(select jsonb_build_object('id',p.id,'nome',p.nome,'email',p.email,'foto_url',p.foto_url,'papel',p.papel,'cargo',p.cargo,'area_id',p.area_id,'ativo',p.ativo,'tipo_membro',p.tipo_membro) from public.profiles p where p.id=auth.uid()),'marcas',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'nome',b.nome,'slug',b.slug) order by b.nome) from public.profile_brands pb join public.brands b on b.id=pb.brand_id where pb.profile_id=auth.uid() and b.ativo),'[]'::jsonb),'convite',(select jsonb_build_object('aceito_em',c.aceito_em,'papel',c.papel,'nome',c.nome) from public.equipe_convites c join public.profiles p on p.id=auth.uid() where lower(c.email)=lower(p.email) limit 1)) end $$;revoke all on function public.meu_acesso() from public,anon;grant execute on function public.meu_acesso() to authenticated;create or replace function app.ao_criar_usuario() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare primeiro boolean;c public.equipe_convites%rowtype;begin select not exists(select 1 from public.profiles where coalesce(tipo_membro,'usuario')='usuario') into primeiro;select * into c from public.equipe_convites where lower(email)=lower(trim(new.email)) limit 1;insert into public.profiles(id,nome,email,foto_url,papel,ativo,area_id,cargo) values(new.id,coalesce(nullif(trim(c.nome),''),nullif(trim(new.raw_user_meta_data->>'nome'),''),nullif(trim(new.raw_user_meta_data->>'full_name'),''),split_part(new.email,'@',1)),lower(new.email),new.raw_user_meta_data->>'avatar_url',case when primeiro then 'admin'::public.papel_usuario when c.email is not null then c.papel else 'membro'::public.papel_usuario end,primeiro or c.email is not null,c.area_id,nullif(trim(c.cargo),'')) on conflict(id) do update set nome=excluded.nome,email=excluded.email,papel=excluded.papel,ativo=excluded.ativo,area_id=excluded.area_id,cargo=excluded.cargo;if primeiro then insert into public.profile_brands(profile_id,brand_id) select new.id,b.id from public.brands b where b.ativo on conflict do nothing;elsif c.email is not null then insert into public.profile_brands(profile_id,brand_id) select new.id,b.id from public.brands b where b.ativo and (cardinality(c.marcas)=0 or b.id=any(c.marcas)) on conflict do nothing;end if;return new;end $$;drop policy if exists equipe_convites_leitura on public.equipe_convites;create policy equipe_convites_leitura on public.equipe_convites for select to authenticated using (app.sou_admin());